<div><div class="card mb-3"><div class="card-header">Employee contracts</div><div class="card-body"><form wire:submit="create" class="row g-2"><div class="col-md-3"><select class="form-select" wire:model="employeeId"><option value="">Employee</option>@foreach($employees as $e)<option value="{{$e->id}}">{{$e->name}}</option>@endforeach</select></div><div class="col-md-2"><select class="form-select" wire:model="type"><option value="indefinite">Indefinite</option><option value="fixed_term">Fixed term</option><option value="temporary">Temporary</option><option value="part_time">Part time</option></select></div><div class="col-md-2"><input class="form-control" type="date" wire:model="startDate"></div><div class="col-md-2"><input class="form-control" type="date" wire:model="endDate"></div><div class="col-md-2"><input class="form-control" placeholder="Contract #" wire:model="contractNumber"></div><div class="col-md-1"><button class="btn btn-primary">Add</button></div></form></div></div>@if($expiring->isNotEmpty())<div class="alert alert-warning"><strong>Expiring within 30 days:</strong> @foreach($expiring as $c)<span class="me-2">{{$c->employee->name}} ({{$c->end_date->toDateString()}})</span>@endforeach</div>@endif<div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Employee</th><th>Type</th><th>Start</th><th>End</th><th>Status</th><th></th></tr></thead><tbody>@foreach($contracts as $c)<tr><td>{{$c->employee->name}}</td><td>{{$c->type}}</td><td>{{$c->start_date->toDateString()}}</td><td>{{$c->end_date?->toDateString()?:'—'}}</td><td>{{$c->status}}</td><td>@if(in_array($c->status,['draft','superseded']))<button wire:click="activate({{$c->id}})" class="btn btn-sm btn-outline-primary">Activate</button>@endif</td></tr>@endforeach</tbody></table></div></div></div>
